929: # -Detach (ROADMAP R12; decisions D1-D12 of its design round): the FOREGROUND - this process, as
930: # the coordinator started it - makes every check a real run makes before it takes the task lock
931: # (the dry run's checks, and the refusals a dry run only reports: the launcher of every engine
932: # that will run, an active recovery record, the preflight - D2), writes the status file once,
933: # state `starting` (Start-DetachedRun), starts the BACKGROUND and exits 0. Not checked in the
934: # foreground: the task lock and the time-dependent health/peak selection - a benign window: the
935: # background is refused then, and its status says so (D3).
936: # The BACKGROUND is `<this host> -File codex-consult.ps1 -Task <t> -CollabDir <absolute> -DetachId
937: # <guid>` in the caller's working directory (D8), its stdout and stderr in the log, started so
938: # that it holds none of the caller's handles: Windows - cmd.exe /c with the redirection, through
939: # ShellExecute, hidden; elsewhere - /bin/sh -c 'exec nohup ...'. Its first action is the self-
940: # report `running` {pid, start_time, host} (D5), then UTF-8 console output (D10), then the
941: # consultation itself IN THIS PROCESS with the foreground's arguments (the `starting` record's
942: # `args`), inside a try/finally that writes the final status {done, exit, summary} whatever the
943: # run did (D3). The run keeps its members' states in the file as they start and finish (D11), and
944: # Stop-WithError records a refusal before it exits ($script:StopWithErrorHook).
945: # -Status / -Wait read status files only (-Prune, the one writing form, deletes old ones): no
946: # lock, no roster, no launcher (D6, D7).
947: 
948: # This script's path (a function of the dot-sourced common file sees THAT file in $PSCommandPath).
949: $script:SelfPath = $PSCommandPath
950: # The parameters of this call (inside a function $PSBoundParameters is the function's own).
951: $script:ScriptBound = @{}
952: foreach ($bk in $PSBoundParameters.Keys) { $script:ScriptBound[$bk] = $PSBoundParameters[$bk] }
953: $script:CommonParameterNames = @([System.Management.Automation.Cmdlet]::CommonParameters) + @([System.Management.Automation.Cmdlet]::OptionalCommonParameters)
954: # The detached run this process is ({ Path; Record }) - set below when -DetachId names it.
955: $script:DetachRun = $null
956: # The summary block a run prints (Write-Summary); a detached run's status file keeps it (D3).
957: $script:SummaryLines = New-Object System.Collections.Generic.List[string]
958: 
959: # One line of the run's summary block: printed, and kept for a detached run's status file.
960: function Write-Summary {
961:     param([string]$Text = '', [string]$Color = '')
962:     if ($Color) { Write-Host $Text -ForegroundColor $Color } else { Write-Host $Text }
963:     $script:SummaryLines.Add($Text)
964: }
965: 
966: # (wave 26, F08-2) A TERMINAL status write (the run's own final write, the background's
967: # confirmation): up to 3 attempts, 250 ms apart. Returns '' when written, else the last error.
968: function Write-DetachedStatusRetry {
969:     param([string]$Path, $Record)
970:     $last = ''
971:     for ($attempt = 1; $attempt -le 3; $attempt++) {
972:         try { Write-DetachedStatus -Path $Path -Record $Record; return '' } catch { $last = ConvertTo-OneLine $_.Exception.Message }
973:         if ($attempt -lt 3) { Start-Sleep -Milliseconds 250 }
974:     }
975:     return $last
976: }
977: 
978: # Writes this detached run's status file. Best effort: a status write never stops the run
979: # (-Final: the terminal write, retried - Write-DetachedStatusRetry).
980: function Save-DetachedRun {
981:     param([switch]$Final)
982:     if (-not $script:DetachRun) { return }
983:     if ($Final) {
984:         $why = Write-DetachedStatusRetry -Path $script:DetachRun.Path -Record $script:DetachRun.Record
985:         if ($why) { Write-Host "codex-consult: could not write the final status to $($script:DetachRun.Path) ($why)" -ForegroundColor Yellow }
986:         return
987:     }
988:     try { Write-DetachedStatus -Path $script:DetachRun.Path -Record $script:DetachRun.Record } catch {
989:         Write-Host "codex-consult: could not update the status file $($script:DetachRun.Path) ($(ConvertTo-OneLine $_.Exception.Message))" -ForegroundColor Yellow
990:     }
991: }
992: 
993: # The members of this detached run - all of them (a panel once its numbers are assigned, a single
994: # run once its reviewer and numbers are known), saved.
995: function Set-DetachedMembers {
996:     param([object[]]$Members)
997:     if (-not $script:DetachRun) { return }
998:     $script:DetachRun.Record.members = [object[]]@($Members | Where-Object { $_ })
999:     Save-DetachedRun
1000: }
1001: 
1002: # Fields of one member of this detached run (by roster position), saved unless -NoSave.
1003: function Set-DetachedMember {
1004:     param([int]$Position, [hashtable]$Values, [switch]$NoSave)
1005:     if (-not $script:DetachRun) { return }
1006:     $m = @($script:DetachRun.Record.members | Where-Object { $_ -and [int]$_.position -eq $Position }) | Select-Object -First 1
1007:     if (-not $m) { return }
1008:     foreach ($k in $Values.Keys) { $m.$k = $Values[$k] }
1009:     if (-not $NoSave) { Save-DetachedRun }
1010: }
1011: 
1012: # The run's own final status (D3), right before it exits: done, the exit code, the summary block
1013: # it printed (Write-Summary) - else $Line. The background confirms it after the run returned.
1014: function Set-DetachedFinal {
1015:     param([int]$Exit, [string]$Line = '')
1016:     if (-not $script:DetachRun) { return }
1017:     $summary = $Line
1018:     if ($script:SummaryLines.Count -gt 0) { $summary = $script:SummaryLines.ToArray() -join "`n" }
1019:     Complete-DetachedRecord -Record $script:DetachRun.Record -Exit $Exit -Summary $summary
1020:     Save-DetachedRun -Final
1021: }
1022: 
1023: # The background's final write (D3), after the run returned or threw: the status file as the run
1024: # left it (else $Fallback, the self-report), made final with the run's real exit code. (wave 26,
1025: # F08-2) Retried (Write-DetachedStatusRetry); returns '' when written, else the error - the
1026: # background then exits 6: the run's result exists only in its log.
1027: function Complete-DetachedRun {
1028:     param([string]$Path, $Fallback, [int]$Exit, [string]$Line = '')
1029:     $rec = $Fallback
1030:     $rd = Read-DetachedStatus -Path $Path
1031:     if ($rd.Record -and [string]$rd.Record.id -eq [string]$Fallback.id) { $rec = $rd.Record }
1032:     Complete-DetachedRecord -Record $rec -Exit $Exit -Line $Line
1033:     $why = Write-DetachedStatusRetry -Path $Path -Record $rec
1034:     if ($why) { Write-Host "codex-consult: could not write the final status to $Path ($why)" -ForegroundColor Red }
1035:     return $why
1036: }
