1038: # -Artifact a,b arrives as ONE string through `powershell -File`: each value is split on commas
1039: # unless the whole value names an existing file (absolute, or relative to one of $Bases).
1040: function Split-ArtifactArgument {
1041:     param([string[]]$Values, [string[]]$Bases)
1042:     $list = New-Object System.Collections.Generic.List[string]
1043:     foreach ($a in @($Values)) {
1044:         if (-not $a -or -not $a.Trim()) { continue }
1045:         $a = $a.Trim()
1046:         $whole = -not $a.Contains(',')
1047:         if (-not $whole) {
1048:             if ([IO.Path]::IsPathRooted($a)) { $whole = Test-Path -LiteralPath $a -PathType Leaf }
1049:             else {
1050:                 foreach ($base in $Bases) {
1051:                     if (Test-Path -LiteralPath (Join-Path $base $a) -PathType Leaf) { $whole = $true; break }
1052:                 }
1053:             }
1054:         }
1055:         if ($whole) { $list.Add($a) }
1056:         else { foreach ($piece in $a.Split(',')) { if ($piece.Trim()) { $list.Add($piece.Trim()) } } }
1057:     }
1058:     return , ([string[]]$list.ToArray())
1059: }
