1012: # The run's own final status (D3), right before it exits: done, the exit code, the summary block
1013: # it printed (Write-Summary) - else $Line. The background confirms it after the run returned.
1014: function Set-DetachedFinal {
1015:     param([int]$Exit, [string]$Line = '')
1016:     if (-not $script:DetachRun) { return }
1017:     $summary = $Line
1018:     if ($script:SummaryLines.Count -gt 0) { $summary = $script:SummaryLines.ToArray() -join "`n" }
1019:     Complete-DetachedRecord -Record $script:DetachRun.Record -Exit $Exit -Summary $summary
1020:     Save-DetachedRun -Final
1021: }
