1045:         $a = $a.Trim()
1046:         $whole = -not $a.Contains(',')
1047:         if (-not $whole) {
1048:             if ([IO.Path]::IsPathRooted($a)) { $whole = Test-Path -LiteralPath $a -PathType Leaf }
1049:             else {
1050:                 foreach ($base in $Bases) {
1122:     } else {
1123:         $q = { param([string]$s) "'" + $s.Replace("'", "'\''") + "'" }
1124:         $bgLine = 'exec nohup ' + (& $q $hostExe) + ' -NoProfile -File ' + (& $q $script:SelfPath) + ' -Task ' + (& $q $Task) + ' -CollabDir ' + (& $q $collabRoot) + ' -DetachId ' + $newId + ' </dev/null >' + (& $q $paths.Log) + ' 2>&1'
1125:     }
1126:     # The `starting` record, written ONCE, before the background exists (D5).
1127:     $rec = ConvertTo-DetachedRecord @{
1128:         status_version = $script:DetachedStatusVersion; id = $newId; id8 = $paths.Id8; task = $Task; kind = $Kind; state = 'starting'
1129:         started = (Get-IsoTimestamp); host = [Environment]::MachineName; budget_sec = $Budget; purpose = $Purpose; reply_name = $ReplyName
1130:         brief = $BriefFull; members = [object[]]@($Members | Where-Object { $_ }); log = $paths.Log; args = (ConvertTo-DetachArgs -Arguments $bgArgs)
1131:         # (wave 27, R13) the coordinator resolved here and the markers the background never gets
1132:         coordinator = $coordinatorRecord; child_env_scrubbed = [object[]]@($childEnvScrubbed)
1133:     }
1134:     try { Write-DetachedStatus -Path $paths.Status -Record $rec } catch {
1135:         $why = ConvertTo-OneLine $_.Exception.Message
1136:         if ($promptFile) { $null = Remove-PendingFile -Path $promptFile }
1137:         Stop-WithError "could not write the status file '$($paths.Status)' ($why); nothing was started."
1138:     }
1139:     # (wave 27, R13 D4) the background (and so every engine child of it) starts without the
1140:     # coordinator's host markers; this process gets them back right after the start
1141:     $bgHidden = $null
1142:     try {
1143:         $bgHidden = Hide-HostMarkers
1144:         if ($script:OnWindows) {
1145:             $cmdExe = [string]$env:ComSpec
1146:             if (-not $cmdExe) { $cmdExe = 'cmd.exe' }
1147:             # ShellExecute (no -NoNewWindow, no redirection here): the background inherits none of
1148:             # this process's handles, so the caller's pipes close when this process exits
1149:             $null = Start-Process -FilePath $cmdExe -ArgumentList $bgLine -WorkingDirectory $callerCwd -WindowStyle Hidden -PassThru
1150:         } else {
