1172:     $collabOpt = $(if ($script:ScriptBound.ContainsKey('CollabDir')) { " -CollabDir `"$collabRoot`"" } else { '' })
1173:     Write-Host "Detached $($paths.Id8): $Plan - it runs in the background (detach id $newId; budget $Budget s)."
