1181: # -Status and -Wait refuse a query with exit 4 - never mistaken for a run's result (D7).
1182: function Stop-StatusQuery {
1183:     param([string]$Message)
1184:     Write-Host "codex-consult: $Message" -ForegroundColor Red
1185:     exit 4
1186: }
