1188: # The -Status report of detached runs (newest first): per run its state, one line per member and,
1189: # when it is done, the summary block the run printed - verbatim.
1190: function Write-DetachedReport {
1191:     param([object[]]$Runs, [DateTimeOffset]$Now = [DateTimeOffset]::Now)
1192:     $first = $true
1193:     foreach ($run in @($Runs)) {
1194:         if (-not $first) { Write-Host '' }
1195:         $first = $false
1196:         $j = Get-DetachedJudgement -Record $run.Record -Problem ([string]$run.Error) -Now $Now
1197:         $rec = $run.Record
1198:         if (-not $rec) {
1199:             Write-Host "detached $($run.Id8): $($j.Text)"
1200:             # (wave 26, F07-1) how it goes away: -Status -Prune 7 days after its last write, or by hand
1201:             $fileAge = $null
1202:             try { $fileAge = $Now - [DateTimeOffset]([IO.File]::GetLastWriteTimeUtc($run.Path)) } catch { }
1203:             if ($fileAge -and $fileAge.TotalDays -ge $script:DetachedPruneDays) { Write-Host "  -Status -Prune removes it (last written $(Format-DetachedSpan $fileAge) ago)" }
1204:             else { Write-Host "  -Status -Prune removes it $($script:DetachedPruneDays) days after its last write; to remove it now: Remove-Item -LiteralPath '$($run.Path)', '$($run.Log)' (the log may say what happened)" }
1205:             continue
1206:         }
1207:         $what = $(if ($rec.kind -eq 'panel') { 'review panel' } else { 'single run' })
1208:         if ($rec.purpose) { $what += ", purpose $($rec.purpose)" }
1209:         if ($rec.reply_name) { $what += ", reply name $($rec.reply_name)" }
1210:         Write-Host "detached $($run.Id8) ($what): $($j.Text)"
1211:         $pidText = $(if ($rec.pid) { "pid $($rec.pid) on $($rec.host)" } else { "no background pid yet (host $($rec.host))" })
1212:         $wallText = $(if ($j.State -eq 'done' -and $null -ne $rec.wall_seconds) { "; wall $($rec.wall_seconds) s" } else { '' })
1213:         Write-Host "  detach id $($rec.id), started $($rec.started), $pidText; budget $($rec.budget_sec) s$wallText"
1214:         foreach ($m in @($rec.members | Where-Object { $_ })) {
1215:             $outcome = [string]$m.outcome
1216:             if ($outcome.StartsWith("$($m.state): ")) { $outcome = $outcome.Substring(([string]$m.state).Length + 2) }
1217:             if ($outcome -eq [string]$m.state) { $outcome = '' }
1218:             $details = New-Object System.Collections.Generic.List[string]
1219:             if ($null -ne $m.n) { $details.Add("n=$($m.n)") }
1220:             if ($m.handoff) { $details.Add("handoff $($m.handoff)") }
1221:             if ($null -ne $m.wall_seconds) { $details.Add("$($m.wall_seconds) s") }
1222:             Write-Host ("  #{0} {1} - {2}{3}{4}" -f $m.position, $m.lineage, $m.state, $(if ($outcome) { ": $outcome" } else { '' }), $(if ($details.Count -gt 0) { " ($($details.ToArray() -join ', '))" } else { '' }))
1223:         }
1224:         Write-Host "  log: $(if ($rec.log) { $rec.log } else { $run.Log })"
1225:         if ($j.State -eq 'done' -and $rec.summary) {
1226:             Write-Host ''
1227:             foreach ($l in ([string]$rec.summary -split "`n")) { Write-Host $l }
1228:         }
1229:     }
1230: }
