453:     if ($recordHost -and $recordHost -ine [Environment]::MachineName) {
454:         return [pscustomobject]@{ State = 'elsewhere'; Exit = 2; Text = "running on host $recordHost since $startedText (pid $bgPid) - its liveness cannot be checked from this host"; Finished = $finished; Of = $of }
455:     }
